import {useState} from 'react';import {api} from '../api';
interface Health {database:boolean;runningJobs:number;pausedFlows:number;failedJobs:number;lastError:string;manualOnly:boolean;configured:{xiaohongshu:boolean;douyin:boolean};}
export function OperationalHealth(){const [health,setHealth]=useState<Health|null>(null),[error,setError]=useState('');return <details className="panel"><summary>任务与服务状态</summary><button className="btn" onClick={()=>void api<Health>('/operational-health').then(h=>{setHealth(h);setError('');}).catch(e=>setError(e.message))}>检查本地状态（不调用付费接口）</button>{error&&<p role="alert">{error}</p>}{health&&<><p>数据库 {health.database?'可读':'异常'} · 运行中 {health.runningJobs} 个任务 · 暂停流程 {health.pausedFlows} 个 · 历史失败任务 {health.failedJobs} 个</p><p>小红书 API 凭证：{health.configured.xiaohongshu?'已配置，真实可用性需验收':'未配置'}；抖音 API 凭证：{health.configured.douyin?'已配置，真实可用性需验收':'未配置或使用浏览器'}。</p>{health.lastError&&<p>最近任务异常：{health.lastError}</p>}<p>自动发送、自动回复、代发与托管已关闭。任务中断后从任务记录核对结果并继续；不会自动重复收费请求。</p></>}</details>;}
